n("ציון", "ציון הוא שמו של הר בירושלים, ובתנ״ך המילה משמשת גם כינוי לירושלים כולה ולעם שיושב בה. בספרי הנביאים חוזרים הרבה הצירופים בת ציון ושיבת ציון. באותו כתיב נכתבת גם המילה ציון, סימן, כמו בצירוף ציון דרך.")
n("ריחאן", "ריחאן היא המילה הערבית לבזיליקום, צמח תבלין שעליו הירוקים מפיצים ריח חזק ונעים כשנוגעים בהם. בערבית המילה מתארת גם כל צמח ריחני, והיא קרובה למילה העברית ריח. ריחאנה היא צורה נוספת של אותו שם.", ["ריחאנה"])
n("תיאה", "תיאה היא המילה היוונית לאלה, והיא הצורה בלשון נקבה של המילה תאוס, אל. מאותה מילה יוונית נבנו גם תיאודור ותיאודורה, וממנה באה גם המילה תאולוגיה, תורת האלוהות. תיאו הוא שם קרוב שבנוי על אותה מילה בלשון זכר.", ["תיאו"])
n("אביאור", "אביאור מחבר את המילים אבי ואור, ופירושו אבי הוא האור שלי. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־אבי, כמו אביעד, אביטל ואביגדור. מאותה מילה, אור, נבנו גם אורי, ליאור ומאור.")
n("אביעד", "אביעד מחבר את המילים אבי ועד, ופירושו אבי לעולם, לתמיד. עד היא מילה עתיקה לנצח, והיא מוכרת מהצירופים לעולם ועד ועדי עד. באותה דרך נבנו שמות עבריים נוספים שמתחילים ב־אבי, כמו אביאור ואביטל.")
n("אוהד", "אוהד הוא מי שאוהב ותומך, ובעברית של היום המילה מוכרת במיוחד מעולם הספורט, אוהדי הקבוצה. מאותו שורש, א־ה־ד, באה גם המילה אהדה, יחס חם וחיובי כלפי מישהו. בעברית הוא נשמע קרוב לשם אהוד, אבל אלה שני שמות שונים.")
n("אוליבר", "אוליבר הוא שם אירופי עתיק, ומקובל לקשר אותו למילה הלטינית אוליבה, זית. עץ הזית גדל בארץ מימי קדם, הוא חי מאות שנים ונותן פרי גם כשהוא זקן. מקור השם אינו ודאי, ויש שמקשרים אותו גם לשמות גרמניים עתיקים.")
n("באר", "באר היא בור עמוק שחופרים באדמה כדי להגיע אל מי התהום. בספר בראשית מסופר על הבארות שחפרו עבדי אברהם ויצחק בנגב, ולכמה מהן ניתנו שמות. מאותה מילה נבנה גם השם בארי, ושם העיר באר שבע בנוי עליה.", ["בארי"])
n("לשם", "לשם היא אחת משתים עשרה האבנים היקרות שהיו משובצות בחושן של הכהן הגדול, בטור השלישי. לא ידוע בוודאות איזו אבן היא, והמפרשים הציעו כמה אבנים שונות. לשם הוא גם שמו של יישוב בשומרון.")
n("עביר", "עביר היא מילה ערבית לניחוח נעים של פרחים, ריח מתוק שעולה מגינה פורחת. בערבית העתיקה המילה מתארת גם תערובת של בשמים. בעברית הפירוש שלו קרוב למילים בושם וניחוח.")
n("עיסאם", "עיסאם היא מילה ערבית להגנה ולשמירה, למה ששומר על אדם ומגן עליו מפני רע. בערבית העתיקה המילה מתארת גם רצועה שקושרים בה נאד של מים, כדי שלא ייפול. בעברית הפירוש שלו קרוב למילים מגן ומחסה.")
n("שי-אל", "שי־אל מחבר את המילים שי ואל, ופירושו מתנה מאלוהים. שי היא מילה עתיקה למתנה, ובעברית של היום אומרים גם שי לחג. באותו פירוש נבנו שמות נוספים, כמו מתנאל ונתנאל, ומאותה מילה נבנה גם השם שי.", ["שי"])
n("גליה", "גליה מחבר את המילה גלים עם יה, קיצור של שם ה׳, ופירושו הגלים של ה׳. גל הוא מים שעולים ויורדים בים, ובעברית העתיקה גל הוא גם ערמה של אבנים. מאותה מילה נבנו גם גל וגלי.", ["גל", "גלי"])
n("דגן", "דגן הוא שם כללי לתבואה, לחיטה, לשעורה ולגרעינים שמהם אופים לחם. בתנ״ך המילה מופיעה הרבה בצירוף דגן, תירוש ויצהר, שלושת היבולים של הארץ. מאותה מילה באה גם המילה דגנים, ובעברית של היום היא מתארת את כל משפחת הצמחים האלה.")
n("הדיל", "הדיל היא מילה ערבית להמיה של יונה, הקול הרך והעמוק שהיונים משמיעות. בשירה הערבית הקול הזה מתאר לא פעם געגועים ואהבה. בעברית הפירוש שלו קרוב למילה המיה, שמתארת את אותו קול.")
n("חביב", "חביב פירושו אהוב, מי שקרוב ללב, והמילה משותפת לעברית ולערבית. מאותו שורש, ח־ב־ב, באות בעברית גם המילים חיבה ומחבב, ובערבית אומרים חביבי, אהובי. חביבה היא הצורה של השם בלשון נקבה.", ["חביבה"])
n("מתנאל", "מתנאל מחבר את המילים מתן ואל, ופירושו מתנה מאלוהים. מתן היא מילה עתיקה למתנה, ומאותו שורש, נ־ת־נ, באות גם המילים נתינה ונתן. מאותה מילה נבנו גם מתן ומתניה.", ["מתן", "מתניה"])
n("נאדיה", "לנאדיה יש שני מקורות. ברוסית זו צורת חיבה של השם נדז'דה, תקווה, ובערבית השם קשור למילה נדא, טל, הטיפות שמופיעות על העשב בבוקר. נדיה הוא כתיב אחר של אותו שם.", ["נדיה"])
n("נימר", "נימר היא המילה הערבית לנמר, החיה ממשפחת החתולים שעורה מנוקד בכתמים. המילה קרובה למילה העברית נמר, ובשתי השפות היא נשמעת כמעט אותו דבר. בעבר חיו נמרים גם במדבר יהודה ובנגב.")
n("פייסל", "פייסל היא מילה ערבית למי ששופט ומכריע, ובמיוחד למי שמבדיל בין אמת לשקר. היא באה משורש שעניינו הפרדה והבחנה, כמו לחתוך בין שני דברים. בעברית הפירוש שלו קרוב למילים שופט ופוסק.")
n("ראמי", "ראמי היא מילה ערבית לקשת, מי שיורה חצים בקשת, והיא באה מהשורש ר־מ־י, לזרוק ולירות. גם בעברית העתיקה הפועל רמה פירושו השליך, מאותו שורש. בעברית הוא נשמע קרוב לשם ראם, אבל הוא בנוי על מילה אחרת.")
n("ראשד", "ראשד היא מילה ערבית למי שנבון ובוגר, שיודע לבחור בדרך הנכונה. היא באה מהשורש ר־ש־ד, שעניינו הדרכה ושיקול דעת, ומאותו שורש בא בערבית גם השם רשיד. בעברית הפירוש שלו קרוב למילה נבון.")
n("רביד", "רביד הוא שרשרת או ענק שעונדים על הצוואר. בספר יחזקאל הרביד מופיע ברשימה של תכשיטים, לצד צמידים, נזם ועגילים. בעברית של היום המילה מוכרת פחות, והיא נשמעת בעיקר כשם. השם ניתן לבנים ולבנות.")
n("שחף", "שחף הוא עוף ים לבן ואפור, עם כנפיים ארוכות, שנראה הרבה מעל חופי הארץ, ובמיוחד בחורף. השחפים ניזונים מדגים ומכל מה שהים פולט אל החוף, והם נוהגים לעקוב אחרי סירות של דייגים. השם ניתן לבנים ולבנות.")
