n("תמיר", "תמיר הוא גבוה וזקוף, ובעברית המילה מתארת קומה גבוהה, כמו של עץ שעומד ישר. מקובל לקשר אותה למילה תמר, עץ הדקל, שגזעו גבוה וזקוף. בעברית של היום המילה מופיעה בעיקר בשירה ובצירוף תמיר קומה.")
n("אריאלה", "אריאלה היא הצורה בלשון נקבה של אריאל, שמחבר את המילים ארי ואל, ופירושו אריה של אלוהים. ארי ואריה הן שתי מילים עתיקות לאותה חיה. אריאל הוא גם שמה של עיר בשומרון.", ["אריאל"])
n("ג'ורג'", "ג'ורג' הוא הצורה האנגלית של השם היווני גאורגיוס, שבנוי על המילה גאורגוס, עובד אדמה, איכר. המילה מחברת שתי מילים יווניות, גה, אדמה, וארגון, עבודה. השם מוכר בשפות רבות, ובכל שפה יש לו צורה משלו, כמו ג'ורג'ו באיטלקית וחורחה בשפה הספרדית.")
n("גד", "גד הוא בנם של יעקב ושל זלפה, שפחתה של לאה, ושבט גד נקרא על שמו. בעברית המקראית גד פירושו מזל, ולכן לאה קראה לו כך כשנולד. שבט גד ישב בעבר הירדן המזרחי, בארץ הגלעד.")
n("דיאנה", "דיאנה היא שם לטיני עתיק, ובמיתולוגיה הרומית זו אלת הירח, הציד והיערות. מקובל לקשר את השם למילה לטינית עתיקה שפירושה אור היום ושמים בהירים. השם עבר מלטינית לשפות רבות באירופה.")
n("ודיע", "ודיע היא מילה ערבית שפירושה שקט, עדין ורגוע, מי שאינו מתרגז ואינו מרים את קולו. היא באה מהשורש ו־ד־ע, שעניינו מנוחה ושלווה. בעברית הפירוש שלו קרוב למילים שליו ועדין.")
n("חאתם", None, note="Old Arabic name whose intro is only a famous person (the poet Hatim al-Tai); the meaning (one who decides) is not certain enough to build a story on.")
n("טוב", "טוב הוא מה שנעים, ראוי והגון, והמילה מוכרת מהעברית העתיקה ועד היום. בעברית אומרים בוקר טוב ויום טוב כשנפגשים. מאותו שורש, ט־ו־ב, באות גם המילים הטבה ומיטב, ומאותה מילה נבנו גם טובה, טוביה וטובי.", ["טובה", "טוביה", "טובי"])
n("לאור", "לאור מחבר את האות ל, שפירושה אל, עם המילה אור, ופירושו אל האור, כמו מי שהולך לקראת האור. בעברית אומרים לצאת לאור על ספר שמתפרסם, ועל דבר שנחשף ונגלה. בעברית הוא נשמע קרוב לשם ליאור, אבל הוא בנוי אחרת.")
n("סוף", "סוף הוא צמח מים, קנה גבוה שגדל בשפת נהרות ואגמים. ים סוף נקרא כך, לפי פירוש מקובל, בגלל הסוף שגדל לחופיו. באותו כתיב נכתבת גם המילה סוף, הקצה שבו דבר נגמר. השם ניתן לבנים ולבנות.")
n("עופר", "עופר הוא צבי צעיר או איל צעיר, ובשיר השירים הדוד, האהוב, מושווה לצבי או לעופר האיילים. עופר הוא גם שמו של מושב בחוף הכרמל. מאותה מילה נבנה גם השם עופרי, העופר שלי.", ["עופרי"])
n("פרומה", "פרומה הוא שם יידי שבא מהמילה הגרמנית פרום, שפירושה אדוק וירא שמים. בגרמנית העתיקה פירוש המילה היה גם הגון, טוב ומועיל. ביידיש פרום הוא מי שמקפיד על המצוות, והמילה מוכרת עד היום.")
n("פריד", "פריד היא מילה ערבית שפירושה יחיד ומיוחד, שאין עוד כמוהו. בערבית המילה מתארת גם פנינה או אבן חן נדירה, שמשובצת במרכזה של שרשרת. בעברית הוא נשמע קרוב לשם פרידה, אבל זה שם אחר.")
n("קים", "קים הוא שם קצר שמשמש בשפות רבות, ובכל שפה יש לו מקור אחר. באנגלית ובשפות אחרות הוא צורה קצרה של שמות ארוכים יותר. בעברית ובארמית קים פירושו קיים ויציב, ומאותו שורש, ק־ו־מ, באות גם המילים קימה ותקומה.")
n("אסינאת", "אסינאת הוא הכתיב הערבי של אסנת, אשתו של יוסף במצרים ואמם של מנשה ואפרים. מקובל לפרש אותו כשם מצרי עתיק, ויש שקושרים אותו לאלה מצרית. אסנת היא הצורה העברית של אותו שם.", ["אסנת"])
n("אסמא", "אסמא היא מילה ערבית שפירושה הנעלה, הגבוהה מכולם, והיא צורת היתרון של המילה סאמי, נעלה. היא באה מהשורש ס־מ־ו, שעניינו גובה ורום. השם מוכר בערבית מימי קדם.")
n("בסמה", "בסמה היא מילה ערבית לחיוך, חיוך אחד, קל ורך. היא באה מהשורש ב־ס־מ, שעניינו חיוך, ומאותו שורש בא בערבית גם השם באסם, מחייך. בעברית היא נשמעת קרוב למילה בושם, אבל היא בנויה על שורש אחר.")
n("ג'נה", "ג'נה היא המילה הערבית לגן, מקום ירוק עם עצים ומים, ובערבית היא גם השם של גן העדן. היא באה מהשורש ג'־נ־נ, שעניינו כיסוי והסתרה, כמו גן שהעצים מכסים אותו בצל, וגם המילה העברית גן קרובה אליה. ג'נאת היא צורת הרבים של אותה מילה.", ["ג'נאת"])
n("הילני", "הילני הוא כתיב אחר של השם הלני, צורה של השם היווני הלנה. מקובל לקשר את השם למילה יוונית שפירושה לפיד או אור, אבל המקור אינו ודאי. הלן היא הצורה של אותו שם בכמה שפות באירופה, כמו אנגלית וצרפתית.", ["הלני", "הלן"])
n("טארק", "טארק היא מילה ערבית למי שדופק בדלת בלילה, ובקוראן היא גם שמו של כוכב השחר, הכוכב המאיר שמופיע בחשכה. היא באה מהשורש ט־ר־ק, שעניינו דפיקה והכאה. בעברית הפירוש שלו קרוב לשם איילת השחר.")
n("יקיר", "יקיר פירושו אהוב ויקר, מי שחשוב ללב. בעברית המילה מוכרת מהתואר יקיר העיר, תואר כבוד שמעניקים לתושב שתרם לעירו. מאותו שורש, י־ק־ר, באות גם המילים יקר והוקרה, ויקירה היא הצורה של השם בלשון נקבה.", ["יקירה"])
n("מואמן", "מואמן היא מילה ערבית למאמין, מי שיש בו אמונה. היא באה מהשורש א־מ־נ, שקיים גם בעברית, ומאותו שורש באות בעברית המילים אמונה, אמן ונאמן. בעברית הוא נשמע קרוב לשם מאמון, אבל זה שם אחר.")
n("מייקל", "מייקל הוא הצורה האנגלית של השם העברי מיכאל, שפירושו מי כאל, מי דומה לאלוהים. השם עבר מעברית ליוונית וללטינית, ומשם לשפות רבות באירופה, ובכל שפה יש לו צורה משלו, כמו מישל בצרפתית ומיגל בשפה הספרדית.", ["מיכאל", "מישל"])
n("אילנה", "אילנה בנוי על המילה אילן, עץ, עם סיומת של לשון נקבה. אילן היא מילה עתיקה לעץ, והיא מוכרת במיוחד מט״ו בשבט, ראש השנה לאילנות. אילן הוא הצורה של השם בלשון זכר.", ["אילן"])
n("איתם", "איתם הוא שם של מקום במדבר, שבו חנו בני ישראל אחרי שיצאו ממצרים, בקצה המדבר, לפני שהגיעו לים. בתורה המקום נכתב בלי יו״ד, אתם. בעברית הוא נשמע קרוב לשם איתמר, אבל זה שם אחר.")
n("אסא", "אסא בן אביה היה מלך יהודה, ומלך בירושלים שנים רבות. בספר מלכים מסופר שהסיר מהארץ את הפסלים ואת עבודת האלילים. מקור השם אינו ודאי, ויש שמקשרים אותו למילה הארמית אסיא, רופא.")
n("ארגמן", "ארגמן הוא צבע אדום־סגול עמוק, ובימי קדם הפיקו אותו מחלזונות ים, בתהליך ארוך ויקר. בתורה הארגמן הוא אחד הצבעים של יריעות המשכן ושל בגדי הכהנים, לצד התכלת ותולעת השני. בגלל מחירו הגבוה, בגדי ארגמן היו בגדים של מלכים.")
n("בושרא", "בושרא היא מילה ערבית לבשורה טובה, ידיעה משמחת שמגיעה פתאום. היא באה מהשורש ב־ש־ר, שקיים גם בעברית, ומאותו שורש באות בעברית המילים בשורה ומבשר. מאותו שורש בא בערבית גם השם בשיר.")
n("דאוד", "דאוד הוא הצורה הערבית של השם דוד, הרועה מבית לחם שנמשח למלך על ישראל. השם מוכר גם במסורת המוסלמית, ובה דאוד הוא מלך ונביא. מקובל לפרש את השם דוד מלשון דוד, אהוב, ודאווד הוא כתיב אחר של אותו שם.", ["דוד", "דאווד"])
n("דועאא", "דועאא היא מילה ערבית לתפילה, ובמיוחד לבקשה אישית שאדם פונה בה במילים שלו. היא באה מהשורש ד־ע־ו, שעניינו קריאה והזמנה. בעברית הפירוש שלו קרוב למילים תפילה ובקשה.")
n("האג'ר", "האג'ר היא הצורה הערבית של השם הגר, שפחתה המצרית של שרה ואמו של ישמעאל. במסורת המוסלמית האג'ר היא דמות חשובה, ועולי הרגל במכה הולכים בעקבות הסיפור שלה על חיפוש המים במדבר. מקור השם אינו ודאי.", ["הגר"])
n("הנא", "הנא היא מילה ערבית לאושר ולשמחה שקטה, הרגשה של טוב ונחת. בערבית אומרים בהנא כשמאחלים למישהו שייהנה מארוחה או ממשהו טוב. בעברית היא נשמעת קרוב למילה הנאה, וגם הפירוש שלהן קרוב.")
n("יאסמינה", "יאסמינה היא צורה של השם יסמין, על שם הפרח הלבן והריחני שמפיץ ריח חזק בערב. המילה באה מהפרסית, ומשם עברה לערבית ולשפות רבות באירופה. יסמין ויסמינה הן צורות אחרות של אותו שם.", ["יסמין", "יסמינה"])
n("מנדל", "מנדל הוא שם יידי, צורת חיבה של השם מנחם, ופירושו כמו פירוש השם העברי, מי שמביא נחמה. ביידיש נבנו צורות חיבה רבות לשמות עבריים, ומנדל היא אחת מהן. מנחם הוא הצורה העברית של אותו שם.", ["מנחם"])
n("נסרין", "נסרין היא המילה הפרסית לוורד בר לבן, שיח פורח עם פרחים קטנים וריחניים. המילה עברה מפרסית לערבית ולשפות נוספות במזרח, ובשירה הפרסית היא מופיעה לצד פרחים אחרים של הגן. בעברית הפירוש שלו קרוב לשם ורד.")
n("סארי", "סארי היא מילה ערבית למי שנוסע בלילה, בחושך, כשהדרכים שקטות. בימי קדם נהגו השיירות במדבר לנסוע בלילה, כשהחום פחות כבד, ולמצוא את הדרך לפי הכוכבים. בעברית הוא נשמע קרוב לשם סארה, אבל זה שם אחר.")
n("עליזה", "עליזה פירושה שמחה, והמילה מתארת מצב רוח טוב וצוהל. היא באה מהשורש ע־ל־ז, שעניינו שמחה וצהלה, ומאותו שורש באות גם המילים עליזות ועלז. בעברית העתיקה השורש הזה מופיע בעיקר בשירה.")
n("פרידא", "פרידא הוא שם יידי וגרמני, ומקובל לקשר אותו לשתי מילים גרמניות, פרידה, שלום, ופרויד, שמחה. ביידיש השם נכתב לפעמים גם פריידא, ואז הוא קרוב יותר למילה שמחה. פרידה הוא כתיב אחר של אותו שם.", ["פרידה"])
n("רעיה", "רעיה היא חברה קרובה ואהובה, ובשיר השירים כך הדוד פונה אל אהובתו פעמים רבות. בעברית של היום רעיה היא גם אשתו של אדם, בלשון גבוהה. מאותה מילה, רע, באה גם המילה רעות, ומאותה מילה נבנה גם השם רעי.", ["רעי"])
n("שטערנא", "שטערנא הוא שם יידי שבא מהמילה ביידיש שטערן, כוכב. ביידיש יש שמות רבים שהם תרגום של שם עברי, ושטערנא ניתן לא פעם יחד עם השם אסתר, שמקובל לקשר אותו לכוכב. בעברית הפירוש שלו קרוב למילה כוכב.")

